-- 2. Monthly revenue (completed orders only)
WITH order_totals AS (
    SELECT o.order_id, o.order_date, SUM(oi.quantity * oi.unit_price) AS order_revenue
    FROM orders o
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.status = 'completed'
    GROUP BY o.order_id, o.order_date
)
SELECT DATE_TRUNC('month', order_date)::DATE AS month,
       SUM(order_revenue) AS monthly_revenue
FROM order_totals
GROUP BY month
ORDER BY month;
/* Output:
month      | monthly_revenue
-----------+----------------
2023-01-01 | 244            
2023-02-01 | 565            
2023-03-01 | 591            
2023-04-01 | 617            
2023-05-01 | 880            
2023-06-01 | 619            
(6 rows)
*/

-- 3. Month-over-month revenue growth (window function: LAG)
WITH monthly AS (
    SELECT DATE_TRUNC('month', o.order_date)::DATE AS month,
           SUM(oi.quantity * oi.unit_price) AS revenue
    FROM orders o
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.status = 'completed'
    GROUP BY month
)
SELECT month,
       revenue,
       LAG(revenue) OVER (ORDER BY month) AS prev_month_revenue,
       ROUND(
           100.0 * (revenue - LAG(revenue) OVER (ORDER BY month))
           / NULLIF(LAG(revenue) OVER (ORDER BY month), 0), 1
       ) AS pct_growth
FROM monthly
ORDER BY month;
/* Output:
month      | revenue | prev_month_revenue | pct_growth
-----------+---------+--------------------+-----------
2023-01-01 | 244     | NULL               | NULL      
2023-02-01 | 565     | 244                | 131.60    
2023-03-01 | 591     | 565                | 4.60      
2023-04-01 | 617     | 591                | 4.40      
2023-05-01 | 880     | 617                | 42.60     
2023-06-01 | 619     | 880                | -29.70    
(6 rows)
*/

-- 4. Running total of revenue over time (window function: SUM OVER)
WITH monthly AS (
    SELECT DATE_TRUNC('month', o.order_date)::DATE AS month,
           SUM(oi.quantity * oi.unit_price) AS revenue
    FROM orders o
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.status = 'completed'
    GROUP BY month
)
SELECT month,
       revenue,
       SUM(revenue) OVER (ORDER BY month) AS running_total
FROM monthly
ORDER BY month;
/* Output:
month      | revenue | running_total
-----------+---------+--------------
2023-01-01 | 244     | 244          
2023-02-01 | 565     | 809          
2023-03-01 | 591     | 1400         
2023-04-01 | 617     | 2017         
2023-05-01 | 880     | 2897         
2023-06-01 | 619     | 3516         
(6 rows)
*/

-- 5. Top 3 products by revenue in each category (window function: RANK)
WITH product_revenue AS (
    SELECT p.category, p.product_name, SUM(oi.quantity * oi.unit_price) AS revenue
    FROM order_items oi
    JOIN products p ON oi.product_id = p.product_id
    GROUP BY p.category, p.product_name
),
ranked AS (
    SELECT *,
           RANK() OVER (PARTITION BY category ORDER BY revenue DESC) AS category_rank
    FROM product_revenue
)
SELECT category, product_name, revenue, category_rank
FROM ranked
WHERE category_rank <= 3
ORDER BY category, category_rank;
