-- 8. Each order's revenue vs. that customer's average order value (window function: AVG OVER)
WITH order_totals AS (
    SELECT o.order_id, o.customer_id, SUM(oi.quantity * oi.unit_price) AS order_revenue
    FROM orders o
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.status = 'completed'
    GROUP BY o.order_id, o.customer_id
)
SELECT order_id, customer_id, order_revenue,
       ROUND(AVG(order_revenue) OVER (PARTITION BY customer_id), 2) AS customer_avg_order,
       order_revenue - AVG(order_revenue) OVER (PARTITION BY customer_id) AS diff_from_avg
FROM order_totals
ORDER BY customer_id, order_id;
