-- 9. New vs. returning customers per month (CTE + window function: ROW_NUMBER)
WITH first_orders AS (
    SELECT customer_id,
           MIN(order_date) AS first_order_date
    FROM orders
    WHERE status = 'completed'
    GROUP BY customer_id
),
monthly_orders AS (
    SELECT o.order_id, o.customer_id, o.order_date,
           DATE_TRUNC('month', o.order_date)::DATE AS order_month,
           DATE_TRUNC('month', f.first_order_date)::DATE AS first_month
    FROM orders o
    JOIN first_orders f ON o.customer_id = f.customer_id
    WHERE o.status = 'completed'
)
SELECT order_month,
       COUNT(*) FILTER (WHERE order_month = first_month) AS new_customer_orders,
       COUNT(*) FILTER (WHERE order_month > first_month) AS returning_customer_orders
FROM monthly_orders
GROUP BY order_month
ORDER BY order_month;
/* Output:
order_month | new_customer_orders | returning_customer_orders
------------+---------------------+--------------------------
2023-01-01  | 4                   | 0                        
2023-02-01  | 2                   | 2                        
2023-03-01  | 4                   | 3                        
2023-04-01  | 3                   | 4                        
2023-05-01  | 2                   | 6                        
2023-06-01  | 1                   | 7                        
(6 rows)
*/